public class PhoneFormatValidator {

    public static boolean isValid(String phone) {
        if (phone == null) {
            return false;
        }
        return phone.matches("(\\(\\d{3}\\) |\\d{3}-)\\d{3}-\\d{4}");
    }

    public static String digitsOnly(String phone) {
        if (phone == null) {
            return "";
        }
        return phone.replaceAll("[^0-9]", "");
    }
}
